$ErrorActionPreference='Continue'
$repo='C:\Users\Xxkan\mhw-mods-work-canonical'
Set-Location $repo
git fetch origin --prune
if($LASTEXITCODE -ne 0){ throw 'fetch failed' }
$active=@()
foreach($line in @(git worktree list --porcelain)){ if($line -like 'branch refs/heads/*'){ $active += $line.Substring(18) } }
$pairs=@(
 @('ui/frontend-ux-overhaul','ui/frontend-responsive-polish-20260928'),
 @('agent/game-profile-id-containment-20260928','agent/game-profile-id-containment-v2-20260928'),
 @('agent/game-profile-id-containment-v2-20260928','agent/game-profile-id-containment-v8.8.5-reconcile'),
 @('agent/replacefilew-failure-characterization-20260927','agent/replacefilew-failure-characterization-v2'),
 @('agent/windows-live-containment-hardening','agent/windows-live-containment-hardening-v2'),
 @('agent/updater-existing-release-rest-ref-gate-20260928','agent/updater-existing-release-rest-ref-gate2-20260928'),
 @('agent-bridge','heaven-bridge'),
 @('agent/reconciliation-continuity-20260929-0542-github','agent/reconciliation-continuity-20260929-final-github'),
 @('agent/reconciliation-continuity-20260929-final-github','agent/reconciliation-continuity-20260929-r3')
)
$deleted=@();$kept=@()
foreach($pair in $pairs){
 $old=$pair[0];$new=$pair[1]
 git show-ref --verify --quiet "refs/remotes/origin/$old"; if($LASTEXITCODE -ne 0){continue}
 git show-ref --verify --quiet "refs/remotes/origin/$new"; if($LASTEXITCODE -ne 0){$kept += [ordered]@{branch=$old;reason='newer-missing';newer=$new};continue}
 if($old -in $active){$kept += [ordered]@{branch=$old;reason='active-worktree';newer=$new};continue}
 git merge-base --is-ancestor "origin/$old" "origin/$new"
 if($LASTEXITCODE -eq 0){
   git push origin --delete $old
   if($LASTEXITCODE -eq 0){$deleted += [ordered]@{branch=$old;proof='ancestor-of-newer';newer=$new}} else {$kept += [ordered]@{branch=$old;reason='delete-failed';newer=$new}}
   continue
 }
 $ch=@(git cherry "origin/$new" "origin/$old" 2>$null)
 $plus=@($ch|Where-Object{$_ -like '+ *'})
 if($plus.Count -eq 0){
   git push origin --delete $old
   if($LASTEXITCODE -eq 0){$deleted += [ordered]@{branch=$old;proof='patch-equivalent-to-newer';newer=$new}} else {$kept += [ordered]@{branch=$old;reason='delete-failed';newer=$new}}
 } else {$kept += [ordered]@{branch=$old;reason='unique-vs-newer';unique=$plus.Count;newer=$new}}
}
git fetch origin --prune | Out-Null
[ordered]@{main=(git rev-parse origin/main);deleted=$deleted;kept=$kept;active_worktrees=$active} | ConvertTo-Json -Depth 6
